function main({raw}){
  let obj = {};
  try {
    obj = JSON.parse(raw);
  } catch (e) {
    obj = { query: String(raw || '').trim(), search_goal: '', focus_dimension: '', use_rules: [] };
  }
  return {
    query: obj.query || String(raw || '').trim(),
    search_goal: obj.search_goal || '',
    focus_dimension: obj.focus_dimension || '',
    use_rules: Array.isArray(obj.use_rules) ? obj.use_rules : []
  };
}

function main({data, query, goal, focus}) {
  const items = Array.isArray(data?.items) ? data.items : [];
  const results = items.slice(0, 5).map((item) => ({
    title: item.title || '',
    link: item.link || '',
    snippet: item.snippet || ''
  }));
  const reference = {
    query,
    search_goal: goal || '',
    focus_dimension: focus || '',
    result_count: results.length,
    results,
    usage_rules: [
      '只提炼职业语感、代际表达、阶层边界、关系礼貌、动作习惯与生活风险感，不直接照抄原句。',
      '优先吸收能帮助角色“说话像活人、反应像活人、决策像活人”的细节。',
      '如检索结果与世界观、主线设定或人物小传冲突，一律以原设定为准。',
      '不得直接移植真实人物经历、现成热梗、爆款句式。'
    ]
  };
  return {
    prompt: JSON.stringify(reference),
    reference_json: JSON.stringify(reference)
  };
}
